class TaskProgress:
    """任务的实时进度。

    ``completed`` 为已经得出结论（通过或失败）的验证项数；
    ``total`` 为整批项数。任务结束前查询不给出最终结果。
    """

    task_id: str
    status: str
    total: int
    completed: int

    @property
    def remaining(self) -> int:
        return self.total - self.completed

    def to_dict(self) -> dict:
        return {
            "task_id": self.task_id,
            "status": self.status,
            "total": self.total,
            "completed": self.completed,
            "remaining": self.remaining,
        }

